/* === runtime.js === */
/* 网站运行时间 */
(function () {
  // 建站日期：2026年4月1日
  var startDate = new Date('2026-04-07T00:00:00')

  function updateRuntime() {
    var now = new Date()
    var diff = now.getTime() - startDate.getTime()
    if (diff < 0) return

    // 计算年月日
    var years = now.getFullYear() - startDate.getFullYear()
    var months = now.getMonth() - startDate.getMonth()
    var days = now.getDate() - startDate.getDate()

    if (days < 0) {
      months--
      var prevMonth = new Date(now.getFullYear(), now.getMonth(), 0)
      days += prevMonth.getDate()
    }
    if (months < 0) {
      years--
      months += 12
    }

    var parts = []
    if (years > 0) parts.push(years + ' 年')
    if (months > 0) parts.push(months + ' 个月')
    if (days >= 0) parts.push(days + ' 天')

    var el = document.getElementById('site-runtime')
    if (el) el.textContent = parts.join(' ')
  }

  // 等待 DOM 就绪
  function init() {
    var footer = document.querySelector('#footer .footer-other')
    if (!footer) {
      // 如果还没加载到，延迟重试
      setTimeout(init, 500)
      return
    }
    // 移除旧的运行时间（避免 PJAX 重复）
    var old = footer.querySelector('.site-runtime-wrap')
    if (old) old.remove()
    var div = document.createElement('div')
    div.className = 'site-runtime-wrap'
    div.innerHTML = '<i class="fas fa-clock"></i> <span class="runtime-label">本站已运行</span> <span id="site-runtime"></span>'
    footer.appendChild(div)
    updateRuntime()
    // 每分钟更新一次
    setInterval(updateRuntime, 60000)
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init)
  } else {
    init()
  }

  // PJAX 导航后重新初始化
  document.addEventListener('pjax:complete', init)
})()

/* === calendar.js === */
/*! Pink Calendar Widget — 支持 PJAX 重新初始化 */
!function(){
  var now = new Date();
  var curYear = now.getFullYear();
  var curMonth = now.getMonth();
  var today = now.getDate();
  var weekNames = ['日','一','二','三','四','五','六'];

  function render(y, m) {
    var firstDay = new Date(y, m, 1).getDay();
    var daysInMonth = new Date(y, m + 1, 0).getDate();
    var prevDays = new Date(y, m, 0).getDate();
    var isCurMonth = (y === curYear && m === curMonth);
    var html = '';

    // Navigation
    html += '<div class="calendar-nav">';
    html += '<button class="cal-prev" title="上月"><i class="fas fa-chevron-left"></i></button>';
    html += '<span class="calendar-title">' + y + '年' + (m + 1) + '月</span>';
    html += '<button class="cal-next" title="下月"><i class="fas fa-chevron-right"></i></button>';
    html += '</div>';

    // Table
    html += '<table class="pink-calendar"><thead><tr>';
    for (var w = 0; w < 7; w++) html += '<th>' + weekNames[w] + '</th>';
    html += '</tr></thead><tbody>';

    var day = 1;
    var nextDay = 1;
    for (var i = 0; i < 6; i++) {
      if (i > 0 && day > daysInMonth) break;
      html += '<tr>';
      for (var j = 0; j < 7; j++) {
        if (i === 0 && j < firstDay) {
          html += '<td class="other-month"><span>' + (prevDays - firstDay + j + 1) + '</span></td>';
        } else if (day > daysInMonth) {
          html += '<td class="other-month"><span>' + (nextDay++) + '</span></td>';
        } else {
          var cls = '';
          if (isCurMonth && day === today) cls = ' today';
          html += '<td class="' + cls + '"><span' + (cls ? ' class="today-span"' : '') + '>' + day + '</span></td>';
          day++;
        }
      }
      html += '</tr>';
    }
    html += '</tbody></table>';
    return html;
  }

  function build() {
    var aside = document.querySelector('#aside-content .sticky_layout') || document.querySelector('#aside-content');
    var announcement = document.querySelector('.card-announcement');
    if (!aside) return;

    // 移除旧的日历（避免 PJAX 重复）
    var old = aside.querySelector('.card-calendar');
    if (old) old.remove();

    var card = document.createElement('div');
    card.className = 'card-widget card-calendar';
    card.innerHTML = '<div class="item-headline"><i class="fas fa-calendar-alt"></i><span>日历</span></div><div class="calendar-body"></div>';

    if (announcement && announcement.parentNode === aside) {
      aside.insertBefore(card, announcement);
    } else {
      aside.insertBefore(card, aside.firstChild);
    }

    var body = card.querySelector('.calendar-body');
    var vy = curYear, vm = curMonth;

    function draw() { body.innerHTML = render(vy, vm); bindNav(); }
    draw();

    function bindNav() {
      var prev = card.querySelector('.cal-prev');
      var next = card.querySelector('.cal-next');
      if (prev) { prev.setAttribute('aria-label', '上个月'); prev.onclick = function() { vm--; if (vm < 0) { vm = 11; vy--; } draw(); }; }
      if (next) { next.setAttribute('aria-label', '下个月'); next.onclick = function() { vm++; if (vm > 11) { vm = 0; vy++; } draw(); }; }
    }
  }

  // 初始化
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', build);
  } else {
    build();
  }

  // PJAX 导航后重新初始化
  document.addEventListener('pjax:complete', build);
}();

/* === category-icons.js === */
/*! 花璃匣 — 分类页图标美化 */
(function () {
  'use strict';

  // 分类名 → 图标映射
  var iconMap = {
    '默认': 'fas fa-folder',
    '技术': 'fas fa-code',
    '编程': 'fas fa-laptop-code',
    '生活': 'fas fa-heart',
    '随笔': 'fas fa-pen-fancy',
    '教程': 'fas fa-book-open',
    '项目': 'fas fa-rocket',
    '资源': 'fas fa-gem',
    '笔记': 'fas fa-sticky-note',
    '前端': 'fas fa-palette',
    '后端': 'fas fa-server',
    '工具': 'fas fa-wrench',
    '设计': 'fas fa-paint-brush',
    '游戏': 'fas fa-gamepad',
    '音乐': 'fas fa-music',
    '摄影': 'fas fa-camera',
    '旅行': 'fas fa-plane',
    '美食': 'fas fa-utensils',
    '读书': 'fas fa-book',
    '影视': 'fas fa-film',
    '日常': 'fas fa-coffee',
    '分享': 'fas fa-share-alt',
    '折腾': 'fas fa-flask',
    '建站': 'fas fa-globe',
    'Hexo': 'fas fa-blog',
    'CSS': 'fab fa-css3-alt',
    'JavaScript': 'fab fa-js',
    'Python': 'fab fa-python',
    'Java': 'fab fa-java',
    'Linux': 'fab fa-linux',
    'Docker': 'fab fa-docker',
    'Git': 'fab fa-git-alt',
    'GitHub': 'fab fa-github'
  };

  var defaultIcon = 'fas fa-folder-open';

  function addIcons() {
    // 分类页面列表
    var categoryLinks = document.querySelectorAll('.category-list a');
    categoryLinks.forEach(function (link) {
      if (link.querySelector('.cat-icon')) return;
      var name = link.textContent.replace(/\d+/g, '').trim();
      var icon = iconMap[name] || defaultIcon;
      var iconEl = document.createElement('i');
      iconEl.className = icon + ' cat-icon';
      iconEl.style.cssText = 'margin-right:6px;font-size:.85em;color:#FF85A2;';
      link.insertBefore(iconEl, link.firstChild);
    });

    // 侧边栏分类卡片
    var cardLinks = document.querySelectorAll('.card-category-list-item a');
    cardLinks.forEach(function (link) {
      if (link.querySelector('.cat-icon')) return;
      var name = link.textContent.replace(/\d+/g, '').trim();
      var icon = iconMap[name] || defaultIcon;
      var iconEl = document.createElement('i');
      iconEl.className = icon + ' cat-icon';
      iconEl.style.cssText = 'margin-right:5px;font-size:.8em;color:#FF85A2;';
      link.insertBefore(iconEl, link.firstChild);
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', addIcons);
  } else {
    addIcons();
  }

  document.addEventListener('pjax:complete', addIcons);
})();

/* === tagcloud-3d.js === */
/*! 花璃匣 — 标签云3D球形动画 */
(function () {
  'use strict';

  var RADIUS = 120;
  var SPEED = 0.3;
  var DEPTH = 300;

  function init() {
    var container = document.querySelector('.tag-cloud-list');
    if (!container) return;

    var links = container.querySelectorAll('a');
    if (links.length < 3) return;

    // 创建3D容器
    var wrapper = document.createElement('div');
    wrapper.className = 'tagcloud-3d';
    wrapper.style.cssText = 'position:relative;width:100%;height:' + (RADIUS * 2 + 40) + 'px;display:flex;align-items:center;justify-content:center;overflow:hidden;';

    var items = [];
    var n = links.length;

    links.forEach(function (link, i) {
      // 球面均匀分布
      var phi = Math.acos(-1 + (2 * i + 1) / n);
      var theta = Math.sqrt(n * Math.PI) * phi;

      var x = RADIUS * Math.cos(theta) * Math.sin(phi);
      var y = RADIUS * Math.sin(theta) * Math.sin(phi);
      var z = RADIUS * Math.cos(phi);

      var el = document.createElement('a');
      el.href = link.href;
      el.textContent = link.textContent;
      el.className = 'tagcloud-3d-item';
      el.style.cssText = 'position:absolute;left:50%;top:50%;white-space:nowrap;cursor:pointer;transition:color .2s,transform .15s;text-decoration:none;';

      items.push({ el: el, x: x, y: y, z: z });
      wrapper.appendChild(el);
    });

    container.innerHTML = '';
    container.appendChild(wrapper);

    var mouseX = 0, mouseY = 0;
    var isHover = false;

    wrapper.addEventListener('mouseenter', function () { isHover = true; });
    wrapper.addEventListener('mouseleave', function () { isHover = false; });
    wrapper.addEventListener('mousemove', function (e) {
      var rect = wrapper.getBoundingClientRect();
      mouseX = (e.clientX - rect.left - rect.width / 2) / (rect.width / 2);
      mouseY = (e.clientY - rect.top - rect.height / 2) / (rect.height / 2);
    });

    // 触摸支持
    wrapper.addEventListener('touchmove', function (e) {
      var touch = e.touches[0];
      var rect = wrapper.getBoundingClientRect();
      mouseX = (touch.clientX - rect.left - rect.width / 2) / (rect.width / 2);
      mouseY = (touch.clientY - rect.top - rect.height / 2) / (rect.height / 2);
    });

    function rotateX(angle) {
      var cos = Math.cos(angle), sin = Math.sin(angle);
      items.forEach(function (item) {
        var y = item.y * cos - item.z * sin;
        var z = item.y * sin + item.z * cos;
        item.y = y; item.z = z;
      });
    }

    function rotateY(angle) {
      var cos = Math.cos(angle), sin = Math.sin(angle);
      items.forEach(function (item) {
        var x = item.x * cos - item.z * sin;
        var z = item.x * sin + item.z * cos;
        item.x = x; item.z = z;
      });
    }

    function render() {
      var autoSpeed = isHover ? 0 : SPEED;
      var targetX = isHover ? mouseY * 0.02 : 0.005;
      var targetY = isHover ? mouseX * 0.02 : 0.008;

      rotateX(targetX + autoSpeed * 0.5);
      rotateY(targetY + autoSpeed);

      items.forEach(function (item) {
        var scale = (DEPTH - item.z) / DEPTH;
        var alpha = Math.max(0.3, scale);
        var size = Math.max(11, 14 * scale);
        item.el.style.transform = 'translate(-50%,-50%) translate(' + item.x + 'px,' + item.y + 'px)';
        item.el.style.fontSize = size + 'px';
        item.el.style.opacity = alpha;
        item.el.style.zIndex = Math.round(scale * 100);
        item.el.style.color = 'var(--tag-color, #C97080)';
      });

      requestAnimationFrame(render);
    }

    render();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }

  document.addEventListener('pjax:complete', init);
})();

/* === gamebox.js === */
/*! 花璃匣 — 游戏展示（竖向自动滚动 + 启匣随机抽取 + PJAX 支持） */
(function () {
  'use strict';

  /* ====== 游戏数据配置 ====== */
  var games = [
    {
      name: '塞尔达传说：王国之泪',
      thumb: '/img/gamebox/zelda-thumb.svg',
      cover: '/img/gamebox/zelda-cover.svg',
      brief: '开放世界动作冒险',
      tags: ['开放世界', '动作', 'Switch'],
      desc: '<p>《塞尔达传说：王国之泪》是任天堂开发的开放世界动作冒险游戏，是《旷野之息》的续作。</p><p>全新的"究极手"等能力带来无限创意玩法，海拉鲁大陆的天空与地底等待探索。</p>'
    },
    {
      name: '星穹铁道',
      thumb: '/img/gamebox/starrail-thumb.svg',
      cover: '/img/gamebox/starrail-cover.svg',
      brief: '银河冒险回合制RPG',
      tags: ['回合制', 'RPG', '二次元'],
      desc: '<p>《崩坏：星穹铁道》是米哈游出品的银河冒险回合制RPG。</p><p>乘坐星穹列车，在星海间旅行，与各种伙伴结交，探索银河的真相。</p>'
    },
    {
      name: '空洞骑士',
      thumb: '/img/gamebox/hollowknight-thumb.svg',
      cover: '/img/gamebox/hollowknight-cover.svg',
      brief: '硬核2D动作冒险',
      tags: ['Metroidvania', '动作', '独立游戏'],
      desc: '<p>《空洞骑士》是一款2D动作冒险游戏，探索广阔而错综复杂的地下昆虫王国。</p><p>极具挑战的战斗、精美的手绘画风、深邃的世界观，是Metroidvania类游戏的巅峰之作。</p>'
    },
    {
      name: '动物森友会',
      thumb: '/img/gamebox/animalcrossing-thumb.svg',
      cover: '/img/gamebox/animalcrossing-cover.svg',
      brief: '悠闲生活模拟',
      tags: ['模拟', '休闲', 'Switch'],
      desc: '<p>《集合啦！动物森友会》是任天堂推出的生活模拟游戏。</p><p>在无人岛上建造自己的家园，与可爱的动物邻居们一起生活，钓鱼、捉虫、装饰，享受慢节奏的岛屿生活。</p>'
    }
  ];

  /* ====== 以下无需修改 ====== */
  if (!games || games.length === 0) return;

  // 随机打乱顺序
  function shuffle(arr) {
    var a = arr.slice();
    for (var i = a.length - 1; i > 0; i--) {
      var j = Math.floor(Math.random() * (i + 1));
      var t = a[i]; a[i] = a[j]; a[j] = t;
    }
    return a;
  }
  var list = shuffle(games);

  var ITEM_H = 72; // 每条高度，与CSS一致
  var INTERVAL = 3500; // 滚动间隔ms

  // 全局弹窗遮罩（跨 PJAX 复用）
  var mask = document.querySelector('.gamebox-modal-mask');
  if (!mask) {
    mask = document.createElement('div');
    mask.className = 'gamebox-modal-mask';
    mask.setAttribute('role', 'dialog');
    mask.setAttribute('aria-modal', 'true');
    mask.setAttribute('aria-label', '游戏详情');
    mask.innerHTML = '<div class="gamebox-modal"><button class="gamebox-modal-close" aria-label="关闭">&times;</button><div id="gamebox-modal-content"></div></div>';
    document.body.appendChild(mask);
  }

  // 打开弹窗
  function openModal(g) {
    var tags = (g.tags || []).map(function (t) { return '<span class="gamebox-modal-tag">' + t + '</span>'; }).join('');
    var isDark = document.documentElement.getAttribute('data-theme') === 'dark';
    var topText = isDark ? '去往下一场璃落' : '去往下一场花开';
    document.getElementById('gamebox-modal-content').innerHTML =
      '<div class="gamebox-modal-top">' + topText + '</div>' +
      '<img class="gamebox-modal-cover" src="' + (g.cover || '/img/gamebox/default-cover.svg') + '" alt="' + g.name + '" onerror="this.src=\'/img/gamebox/default-cover.svg\'">' +
      '<div class="gamebox-modal-body">' +
      '<div class="gamebox-modal-name">' + g.name + '</div>' +
      (tags ? '<div class="gamebox-modal-tags">' + tags + '</div>' : '') +
      '<div class="gamebox-modal-desc">' + g.desc + '</div></div>';
    mask.classList.add('active');
    document.body.style.overflow = 'hidden';
  }

  function closeModal() {
    mask.classList.remove('active');
    document.body.style.overflow = '';
  }

  // 弹窗关闭事件（只绑定一次）
  if (!mask._bindClose) {
    mask.querySelector('.gamebox-modal-close').addEventListener('click', closeModal);
    mask.addEventListener('click', function (e) { if (e.target === mask) closeModal(); });
    document.addEventListener('keydown', function (e) { if (e.key === 'Escape') closeModal(); });
    mask._bindClose = true;
  }

  function build() {
    var aside = document.getElementById('aside-content');
    if (!aside) { setTimeout(build, 300); return; }

    var announcement = aside.querySelector('.card-announcement');

    // 移除旧的花璃匣（避免 PJAX 重复）
    var oldCard = aside.querySelector('.card-gamebox');
    if (oldCard) oldCard.remove();

    // 构建HTML：首项 + 随机列表 + 首项（无缝循环）
    var html = list.map(function (g, i) {
      return '<div class="gamebox-item" data-index="' + i + '">' +
        '<img class="gamebox-thumb" src="' + (g.thumb || '/img/gamebox/default-thumb.svg') + '" alt="' + g.name + '" loading="lazy" onerror="this.src=\'/img/gamebox/default-thumb.svg\'">' +
        '<div class="gamebox-text"><div class="gamebox-name">' + g.name + '</div><div class="gamebox-brief">' + g.brief + '</div></div>' +
        '</div>';
    }).join('');

    var card = document.createElement('div');
    card.className = 'card-widget card-gamebox';
    card.innerHTML =
      '<div class="gamebox-header">' +
        '<div class="item-headline"><i class="fas fa-gamepad"></i><span>花璃匣</span></div>' +
        '<button class="gamebox-lucky-btn" title="随机抽取">启匣</button>' +
      '</div>' +
      '<div class="gamebox-viewport"><div class="gamebox-track">' + html + '</div></div>';

    // 插入到公告下方
    if (announcement && announcement.nextSibling) {
      aside.insertBefore(card, announcement.nextSibling);
    } else {
      aside.appendChild(card);
    }

    // 自动滚动
    var track = card.querySelector('.gamebox-track');
    var idx = 0;
    var total = list.length;
    var paused = false;

    // hover暂停
    card.addEventListener('mouseenter', function () { paused = true; });
    card.addEventListener('mouseleave', function () { paused = false; });

    setInterval(function () {
      if (paused) return;
      idx++;
      track.style.transform = 'translateY(-' + (idx * ITEM_H) + 'px)';

      // 无缝循环：滚到克隆项后瞬间跳回
      if (idx >= total) {
        setTimeout(function () {
          track.style.transition = 'none';
          idx = 0;
          track.style.transform = 'translateY(0)';
          // 强制重绘后恢复过渡
          void track.offsetHeight;
          track.style.transition = 'transform .5s cubic-bezier(.4,0,.2,1)';
        }, 520);
      }
    }, INTERVAL);

    // 点击卡片打开弹窗
    card.addEventListener('click', function (e) {
      var btn = e.target.closest('.gamebox-lucky-btn');
      if (btn) return; // 启匣按钮单独处理
      var item = e.target.closest('.gamebox-item');
      if (!item) return;
      var i = parseInt(item.getAttribute('data-index'));
      var g = list[i];
      if (!g) return;
      openModal(g);
    });

    // 启匣按钮：随机抽取
    card.querySelector('.gamebox-lucky-btn').addEventListener('click', function (e) {
      e.stopPropagation();
      var ri = Math.floor(Math.random() * list.length);
      openModal(list[ri]);
    });
  }

  // 初始化
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', build);
  } else {
    build();
  }

  // PJAX 导航后重新初始化
  document.addEventListener('pjax:complete', build);
})();

/* === mobile-toc.js === */
/*! Mobile TOC — 手机端目录默认隐藏，按钮切换开合 */
(function () {
  'use strict';

  function init() {
    var toc = document.getElementById('card-toc');
    if (!toc) return;

    // 确保手机端初始状态：面板关闭 + 子目录折叠
    if (window.innerWidth <= 900) {
      toc.classList.remove('open');
      toc.setAttribute('aria-expanded', 'false');
      var content = toc.querySelector('.toc-content');
      if (content) content.classList.remove('is-expand');
    } else {
      toc.setAttribute('aria-expanded', 'true');
    }

    // 监听面板开关，同步 aria-expanded + 子目录折叠
    var observer = new MutationObserver(function () {
      var isOpen = toc.classList.contains('open');
      toc.setAttribute('aria-expanded', isOpen ? 'true' : 'false');
      if (isOpen && window.innerWidth <= 900) {
        var content = toc.querySelector('.toc-content');
        if (content) content.classList.remove('is-expand');
      }
    });
    observer.observe(toc, { attributes: true, attributeFilter: ['class'] });

    // 点击面板外部关闭
    document.addEventListener('click', function (e) {
      if (window.innerWidth > 900) return;
      if (!toc.classList.contains('open')) return;
      if (toc.contains(e.target)) return;
      if (e.target.closest('#mobile-toc-button')) return;
      toc.classList.remove('open');
    });
  }

  // 初始化 + PJAX 兼容
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
  document.addEventListener('pjax:complete', init);
})();

/* === music-lazy-loader.js === */
/*! Pink Music Lazy Loader - 点击才加载APlayer，首次访问零音频开销 */
(function () {
  'use strict';

  // 创建浮动音乐按钮
  var btn = document.createElement('div');
  btn.id = 'pink-music-btn';
  btn.innerHTML = '<svg viewBox="0 0 24 24" width="22" height="22" fill="currentColor"><path d="M12 3v10.55c-.59-.34-1.27-.55-2-.55C7.79 13 6 14.79 6 17s1.79 4 4 4 4-1.79 4-4V7h4V3h-6z"/></svg>';
  btn.setAttribute('role', 'button');
  btn.setAttribute('aria-label', '点击播放音乐');
  btn.setAttribute('tabindex', '0');
  var style = document.createElement('style');
  style.textContent = '#pink-music-btn{position:fixed;left:20px;bottom:80px;width:44px;height:44px;border-radius:50%;background:linear-gradient(135deg,#FF85A2,#FFB6C1);color:#fff;display:flex;align-items:center;justify-content:center;cursor:pointer;z-index:999;box-shadow:0 2px 12px rgba(255,133,162,.4);transition:transform .2s,box-shadow .2s;animation:pink-pulse 2s infinite}#pink-music-btn:hover{transform:scale(1.1);box-shadow:0 4px 20px rgba(255,133,162,.6)}@keyframes pink-pulse{0%,100%{box-shadow:0 2px 12px rgba(255,133,162,.4)}50%{box-shadow:0 2px 20px rgba(255,133,162,.7)}}#pink-music-btn.loading{opacity:.6;pointer-events:none;animation:none}';
  document.head.appendChild(style);
  document.body.appendChild(btn);

  var loaded = false;
  var loading = false;

  function loadScript(src, cb) {
    var s = document.createElement('script');
    s.src = src;
    s.onload = cb;
    s.onerror = function () { console.warn('[MusicLoader] Failed: ' + src); btn.classList.remove('loading'); };
    document.body.appendChild(s);
  }

  function loadCSS(href) {
    var l = document.createElement('link');
    l.rel = 'stylesheet';
    l.href = href;
    document.head.appendChild(l);
  }

  btn.addEventListener('click', function () {
    if (loaded || loading) return;
    loading = true;
    btn.classList.add('loading');
    btn.setAttribute('aria-busy', 'true');

    // 加载APlayer CSS
    loadCSS('/css/APlayer.min.css');

    // 加载APlayer JS，完成后加载music-player.js
    loadScript('/js/APlayer.min.js', function () {
      loadScript('/js/music-player.js', function () {
        loaded = true;
        btn.style.display = 'none';
      });
    });
  });

  // 键盘支持
  btn.addEventListener('keydown', function (e) {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      btn.click();
    }
  });
})();